class Solution {
public:
    vector<int> lastVisitedIntegers(vector<int>& nums) {
        vector<int> seen, ans;
        int k = 0;
        for (int x : nums) {
            if (x != -1) { seen.insert(seen.begin(), x); k = 0; }
            else {
                k++;
                ans.push_back(k <= (int)seen.size() ? seen[k - 1] : -1);
            }
        }
        return ans;
    }
};

