class Solution {
    public List<Integer> lastVisitedIntegers(int[] nums) {
        LinkedList<Integer> seen = new LinkedList<>();
        List<Integer> ans = new ArrayList<>();
        int k = 0;
        for (int x : nums) {
            if (x != -1) { seen.addFirst(x); k = 0; }
            else {
                k++;
                ans.add(k <= seen.size() ? seen.get(k - 1) : -1);
            }
        }
        return ans;
    }
}

